// Truchet tiles: every square holds two quarter-circle arcs, turned one way or the other
// at random. Side by side they join into long winding paths. A wave sweeps across and
// flips the tiles it passes.
#define PI 3.14159265

// A pseudo-random number for each tile.
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  // Coordinates with (0, 0) in the middle, and y from -1 to 1.
  vec2 uv = (2.0 * fragCoord - iResolution.xy) / iResolution.y;

  // Split the screen into tiles, drifting slowly to the left.
  float scale = 5.0;
  vec2 p = uv * scale + vec2(0.4 * iTime, 0.0);
  vec2 tile = floor(p);
  vec2 f = fract(p) - 0.5;

  // Each tile is turned at random, and turned again while the wave is over it.
  float wave = step(0.0, sin(0.8 * iTime - 0.35 * (tile.x + 0.5 * tile.y)));
  if (mod(floor(2.0 * hash(tile)) + wave, 2.0) > 0.5) {
    f.x = -f.x;
  }

  // The distance to the nearer arc. The arcs are centred on opposite corners.
  float d = min(abs(length(f - 0.5) - 0.5), abs(length(f + 0.5) - 0.5));
  float pixel = 2.0 * scale / iResolution.y;
  float line = smoothstep(0.12 + pixel, 0.12, d);

  vec3 background = vec3(0.06, 0.07, 0.12);
  vec3 lineColor = 0.6 + 0.4 * cos(2.0 * PI * (0.06 * (tile.x - tile.y) + vec3(0.0, 0.15, 0.3)));
  fragColor = vec4(mix(background, lineColor, line), 1.0);
}
